import net.sf.jsqlparser.parser.CCJSqlParserUtil;
import net.sf.jsqlparser.statement.Statement;
import net.sf.jsqlparser.statement.select.*;
import com.github.pagehelper.PageException;

public String convertToPageSql(String sql, Integer offset, Integer limit) {
    try {
        Statement stmt = CCJSqlParserUtil.parse(sql);

        if (!(stmt instanceof Select)) {
            throw new PageException("Pagination statement must be a SELECT query!");
        }

        Select select = (Select) stmt;
        PlainSelect plainSelect = (PlainSelect) select.getSelectBody();

        if (plainSelect.getOrderByElements() == null) {
            throw new PageException("Pagination query must have an ORDER BY clause for pagination!");
        }

        if (offset == null) {
            offset = 0;
        }

        if (limit != null) {
            plainSelect.setTop(limit);
        }

        // Create ROW_NUMBER() and wrap the original query
        SelectExpressionItem rowNumItem = new SelectExpressionItem(new Column("ROW_NUMBER() OVER(ORDER BY (SELECT NULL))"));
        plainSelect.getSelectItems().add(0, rowNumItem);

        SubSelect innerSelect = new SubSelect();
        innerSelect.setSelectBody(select.getSelectBody());
        innerSelect.setAlias(new Alias("inner_query"));

        Select outerSelect = new Select();
        outerSelect.setSelectBody(innerSelect);
        outerSelect.setTop(new Top(offset));

        // Create the final pagination SQL query
        Select finalSelect = new Select();
        PlainSelect finalPlainSelect = new PlainSelect();
        finalPlainSelect.setSelectItems(plainSelect.getSelectItems());
        finalPlainSelect.setFromItem(outerSelect);
        finalPlainSelect.setOrderByElements(plainSelect.getOrderByElements());

        finalSelect.setSelectBody(finalPlainSelect);

        return finalSelect.toString();
    } catch (Throwable e) {
        throw new PageException("Failed to parse SQL query for pagination!", e);
    }
}

